CREATE TABLE `st_ordenes_servicio` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `numero_orden` varchar(50) NOT NULL,
  `st_cliente_id` bigint(20) unsigned NOT NULL,
  `st_equipo_id` bigint(20) unsigned DEFAULT NULL,
  `st_tecnico_id` bigint(20) unsigned DEFAULT NULL,
  `tipo_servicio` varchar(255) NOT NULL,
  `prioridad` varchar(20) NOT NULL DEFAULT 'media',
  `estado` varchar(30) NOT NULL DEFAULT 'recibida',
  `descripcion_problema` text NOT NULL,
  `accesorios_entregados` text DEFAULT NULL,
  `fecha_recepcion` date NOT NULL,
  `fecha_promesa_entrega` date DEFAULT NULL,
  `fecha_asignacion` date DEFAULT NULL,
  `fecha_inicio_trabajo` date DEFAULT NULL,
  `fecha_finalizacion` date DEFAULT NULL,
  `fecha_entrega` date DEFAULT NULL,
  `costo_mano_obra` decimal(12,2) DEFAULT NULL,
  `costo_repuestos` decimal(12,2) DEFAULT NULL,
  `costo_total` decimal(12,2) DEFAULT NULL,
  `cliente_notificado` tinyint(1) NOT NULL DEFAULT 0,
  `observaciones` text DEFAULT NULL,
  `user_id` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `st_ordenes_servicio_numero_orden_unique` (`numero_orden`),
  KEY `st_ordenes_servicio_st_cliente_id_foreign` (`st_cliente_id`),
  KEY `st_ordenes_servicio_st_equipo_id_foreign` (`st_equipo_id`),
  KEY `st_ordenes_servicio_st_tecnico_id_foreign` (`st_tecnico_id`),
  KEY `st_ordenes_servicio_user_id_foreign` (`user_id`),
  CONSTRAINT `st_ordenes_servicio_st_cliente_id_foreign` FOREIGN KEY (`st_cliente_id`) REFERENCES `st_clientes` (`id`),
  CONSTRAINT `st_ordenes_servicio_st_equipo_id_foreign` FOREIGN KEY (`st_equipo_id`) REFERENCES `st_equipos` (`id`),
  CONSTRAINT `st_ordenes_servicio_st_tecnico_id_foreign` FOREIGN KEY (`st_tecnico_id`) REFERENCES `st_tecnicos` (`id`) ON DELETE SET NULL,
  CONSTRAINT `st_ordenes_servicio_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=33 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
